    content: "pymupdf>=1.26\nrequests>=2.31\nnumpy>=2.0\nopencv-python-headless>=4.10\nscipy>=1.11\nscikit-image>=0.22\nscikit-learn>=1.4\njoblib>=1.3\nPillow>=10.0\nrdkit>=2024.3\nhuggingface_hub>=0.20\nultralytics>=8.3\n",
